// VISUAL DE PAZ: camara que respira, polvo de luz, luz dorada, cambios con destello suave. Sin SFX (FE: solo voz y musica suave).
export const SUBS={arriba:200,size:80,acento:'#FFD84D'};
type C3=[string,string,string];
const q=(s:number,a:number,b:number)=>interpolate(s,[a,Math.max(a+.01,b)],[0,1],{...clamp,easing:Easing.inOut(Easing.cubic)});
const L=(a:number,b:number,p:number)=>a+(b-a)*p;
const ell=(cx:number,cy:number,rx:number,ry:number)=>`M${cx-rx} ${cy}a${rx} ${ry} 0 1 0 ${2*rx} 0a${rx} ${ry} 0 1 0 ${-2*rx} 0Z`;
const caps=(x1:number,y1:number,x2:number,y2:number,w:number)=>{const a=Math.atan2(y2-y1,x2-x1),r=w/2,nx=-Math.sin(a)*r,ny=Math.cos(a)*r;
 return `M${x1+nx} ${y1+ny}L${x2+nx} ${y2+ny}A${r} ${r} 0 0 0 ${x2-nx} ${y2-ny}L${x1-nx} ${y1-ny}A${r} ${r} 0 0 0 ${x1+nx} ${y1+ny}Z`;};
const rr=(x:number,y:number,w:number,h:number,r:number)=>`M${x+r} ${y}H${x+w-r}Q${x+w} ${y} ${x+w} ${y+r}V${y+h-r}Q${x+w} ${y+h} ${x+w-r} ${y+h}H${x+r}Q${x} ${y+h} ${x} ${y+h-r}V${y+r}Q${x} ${y} ${x+r} ${y}Z`;
const poly=(p:number[][])=>'M'+p.map(a=>a.join(' ')).join('L')+'Z';
const AN:C3=['#f0bd94','#c98a5e','#8a5030'],SK2:C3=['#ffe2c9','#f0a57e','#a4563a'],SK3:C3=['#b57a52','#7e4a2a','#3a1c0a'],HAIR:C3=['#55403c','#1d1414','#050303'],HAIR2:C3=['#a0785a','#5a3a22','#1e1008'],HAIR3:C3=['#c9c9d6','#6a6a7e','#22222e'];
const CORAL:C3=['#ffc2ac','#ff6f5e','#ab2a2e'],NAVY:C3=['#7088f0','#2a3fb4','#0e1a60'],WHITE:C3=['#ffffff','#e9effa','#a9b8d6'],GLASS:C3=['#e2fbff','#6fd0ec','#1f7fa8'],RED:C3=['#ff9288','#e11d2e','#74001a'];
const GOLD:C3=['#fff6bd','#ffc93a','#b57a00'],GREEN:C3=['#9dffc8','#12b981','#065f46'],BLUE:C3=['#9bbcff','#1f6bff','#0a2a8a'],DARK:C3=['#6a7a9a','#222b44','#070a18'],SHOE:C3=['#6c6c82','#262636','#07070e'],VIO:C3=['#b9a2ff','#5a35d6','#1c0a6a'];
const Vol:React.FC<{id:string;d:string;c:C3;sw?:number;o?:number;borde?:string;bl?:string}>=({id,d,c,sw=70,o=24,borde,bl='b18'})=><g>
 <defs><clipPath id={id}><path d={d}/></clipPath></defs>
