  <path d={d} fill='none' stroke={c[0]} strokeWidth={sw*.75} filter={`url(#${bl})`} transform={`translate(${o} ${o})`}/>
 </g>
 <path d={d} fill='none' stroke={borde||c[2]} strokeWidth={3} opacity={.55}/>
</g>;
const Brillo2:React.FC<{x:number;y:number;rx:number;ry:number;r?:number;o?:number}>=({x,y,rx,ry,r=-30,o=.75})=><ellipse cx={x} cy={y} rx={rx} ry={ry} transform={`rotate(${r} ${x} ${y})`} fill='#fff' opacity={o} filter='url(#b6)'/>;
const Brazo:React.FC<{id:string;p:number[][];w:number;c:C3;ex?:string}>=({id,p,w,c,ex=''})=>{
 const d=p.slice(0,-1).map((a,i)=>caps(a[0],a[1],p[i+1][0],p[i+1][1],w)).join('')+ex,ln='M'+p.map(a=>a.join(' ')).join('L'),bl=w>100?'b18':'b6',k=w*.12;
