   <path d={ln} stroke={c[1]} strokeWidth={w*.9} fill='none' strokeLinecap='round' strokeLinejoin='round' filter={`url(#${bl})`} transform={`translate(${-k} ${-k})`}/>
   <path d={ln} stroke={c[0]} strokeWidth={w*.36} fill='none' strokeLinecap='round' strokeLinejoin='round' filter={`url(#${bl})`} transform={`translate(${-k*2} ${-k*2})`}/>
  </g></g>;};
