   {ring&&f.j===2&&<g transform={`translate(${f.x+(f.tx-f.x)*.36} ${f.y+(f.ty-f.y)*.36}) rotate(${f.an*180/Math.PI})`}><path d='M-17 0Q0 6 17 0' stroke='#b8860b' strokeWidth={8} fill='none'/><path d='M-16 -2Q0 3 16 -2' stroke='#fff3b0' strokeWidth={3} fill='none'/></g>}
